package com.namazim

import org.junit.Assert.assertTrue
import org.junit.Test
import java.time.Instant
import java.time.LocalDate
import java.time.ZoneId

/** Our times vs Diyanet's published Nov 2026 tables (namazvakitleri.diyanet.gov.tr). */
class DiyanetMatchTest {
    // imsak güneş öğle ikindi akşam yatsı, Nov 1..30
    private val ank = """05:46 07:10 12:37 15:27 17:54 19:14;05:47 07:11 12:37 15:27 17:53 19:12;05:48 07:12 12:37 15:26 17:52 19:11;05:49 07:14 12:37 15:25 17:51 19:10;05:50 07:15 12:37 15:24 17:50 19:09;05:51 07:16 12:37 15:23 17:49 19:09;05:52 07:17 12:37 15:22 17:48 19:08;05:53 07:18 12:37 15:21 17:47 19:07;05:54 07:19 12:37 15:21 17:46 19:06;05:55 07:20 12:37 15:20 17:45 19:05;05:56 07:22 12:38 15:19 17:44 19:04;05:57 07:23 12:38 15:18 17:43 19:03;05:58 07:24 12:38 15:18 17:42 19:03;05:59 07:25 12:38 15:17 17:41 19:02;06:00 07:26 12:38 15:16 17:40 19:01;06:01 07:27 12:38 15:16 17:39 19:01;06:02 07:28 12:38 15:15 17:39 19:00;06:03 07:30 12:39 15:14 17:38 19:00;06:03 07:31 12:39 15:14 17:37 18:59;06:04 07:32 12:39 15:13 17:36 18:58;06:05 07:33 12:39 15:13 17:36 18:58;06:06 07:34 12:40 15:12 17:35 18:58;06:07 07:35 12:40 15:12 17:35 18:57;06:08 07:36 12:40 15:12 17:34 18:57;06:09 07:37 12:40 15:11 17:34 18:56;06:10 07:38 12:41 15:11 17:33 18:56;06:11 07:40 12:41 15:11 17:33 18:56;06:12 07:41 12:41 15:10 17:32 18:56;06:13 07:42 12:42 15:10 17:32 18:55;06:14 07:43 12:42 15:10 17:32 18:55"""
    private val ist = """06:02 07:28 12:53 15:41 18:08 19:29;06:03 07:29 12:53 15:40 18:07 19:27;06:04 07:30 12:53 15:39 18:05 19:26;06:05 07:31 12:53 15:38 18:04 19:25;06:06 07:32 12:53 15:37 18:03 19:24;06:07 07:33 12:53 15:36 18:02 19:23;06:08 07:35 12:53 15:35 18:01 19:22;06:09 07:36 12:53 15:34 18:00 19:21;06:10 07:37 12:53 15:34 17:59 19:21;06:11 07:38 12:53 15:33 17:58 19:20;06:12 07:39 12:53 15:32 17:57 19:19;06:13 07:41 12:53 15:31 17:56 19:18;06:14 07:42 12:53 15:30 17:55 19:17;06:15 07:43 12:53 15:30 17:54 19:17;06:16 07:44 12:54 15:29 17:53 19:16;06:17 07:45 12:54 15:28 17:52 19:15;06:18 07:47 12:54 15:28 17:51 19:15;06:19 07:48 12:54 15:27 17:51 19:14;06:20 07:49 12:54 15:27 17:50 19:13;06:21 07:50 12:55 15:26 17:49 19:13;06:22 07:51 12:55 15:26 17:49 19:12;06:23 07:52 12:55 15:25 17:48 19:12;06:24 07:53 12:55 15:25 17:47 19:11;06:25 07:55 12:56 15:24 17:47 19:11;06:26 07:56 12:56 15:24 17:46 19:11;06:27 07:57 12:56 15:23 17:46 19:10;06:28 07:58 12:57 15:23 17:45 19:10;06:29 07:59 12:57 15:23 17:45 19:10;06:30 08:00 12:57 15:23 17:44 19:09;06:31 08:01 12:58 15:22 17:44 19:09"""

    private fun check(lat: Double, lng: Double, table: String) {
        val z = ZoneId.of("Europe/Istanbul")
        var exact = 0
        table.split(";").forEachIndexed { d, row ->
            val want = row.trim().split(" ").map { it.split(":").let { (h, m) -> h.toInt() * 60 + m.toInt() } }
            val t = dayTimes(lat, lng, LocalDate.of(2026, 11, d + 1))
            val got = listOf(t.imsak, t.gunes, t.ogle, t.ikindi, t.aksam, t.yatsi)
                .map { Instant.ofEpochMilli(it).atZone(z).toLocalTime().toSecondOfDay() / 60 }
            got.zip(want).forEach { (g, w) ->
                assertTrue("day ${d + 1}: got $g want $w", kotlin.math.abs(g - w) <= 1)
                if (g == w) exact++
            }
        }
        assertTrue("only $exact/180 exact", exact >= 160)
    }

    @Test fun ankara() = check(39.9208, 32.8541, ank)
    @Test fun istanbul() = check(41.0082, 28.9784, ist)
}
